from collections import OrderedDict

class LRUMemory:
    def __init__(self, capacity):
        self.cap = capacity
        self.items = OrderedDict()

    def touch(self, key, value):
        self.items[key] = value
        self.items.move_to_end(key)      # mark most-recently-used
        if len(self.items) > self.cap:
            self.items.popitem(last=False)  # evict least-recently-used

def dedup_exact(memories):
    seen, kept = set(), []
    for m in memories:
        norm = m["text"].strip().lower()
        if norm in seen:
            continue                 # drop the repeat
        seen.add(norm)
        kept.append(m)
    return kept
# for paraphrases, merge when cosine(a, b) > 0.95 instead

def filter_and_reconcile(hits, min_score=0.3):
    hits = [h for h in hits if h["score"] >= min_score]  # drop weak matches
    # if two hits about the same key conflict, keep the newest
    by_key = {}
    for h in sorted(hits, key=lambda x: x["ts"]):        # oldest first
        by_key[h["key"]] = h                             # newest overwrites
    return list(by_key.values())
